#define main protocol_main
#include "protocol_test.c"
#undef main
static uint32_t word(const unsigned char *p){return ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3];}
static void read_exact(int fd,unsigned char *p,size_t n){while(n){struct pollfd f={fd,POLLIN,0};CHECK(poll(&f,1,6500)>0);ssize_t r=recv(fd,p,n,0);CHECK(r>0);p+=r;n-=r;}}
static uint32_t report(int fd,unsigned packets,unsigned octets){unsigned char b[512];read_exact(fd,b,4);CHECK(b[0]=='$'&&b[1]==3);size_t n=((unsigned)b[2]<<8)|b[3];CHECK(n>=44&&n<=296);read_exact(fd,b,n);CHECK(b[0]==0x80&&b[1]==200&&b[2]==0&&b[3]==6);uint32_t ssrc=word(b+4);CHECK(ssrc);CHECK(word(b+20)==packets&&word(b+24)==octets);struct timespec real,mono;CHECK(clock_gettime(CLOCK_REALTIME,&real)==0);CHECK(clock_gettime(CLOCK_MONOTONIC,&mono)==0);uint32_t ntp=(uint32_t)((uint64_t)real.tv_sec+2208988800ULL);CHECK((uint32_t)(ntp-word(b+8))<=1);uint32_t ticks=(uint32_t)((uint64_t)mono.tv_sec*90000+(uint64_t)mono.tv_nsec*9/100000);CHECK((uint32_t)(ticks-word(b+16))<90000);CHECK(b[28]==0x81&&b[29]==202);CHECK(word(b+32)==ssrc);CHECK(b[36]==1);char cname[48];snprintf(cname,sizeof(cname),"owned-%08x@divinus",ssrc);CHECK(b[37]==strlen(cname)&&!memcmp(b+38,cname,strlen(cname)));return ssrc;}
int main(void){struct rtsp_owned_options o={"127.0.0.1","u","p",0,stopped,failure,NULL};rtsp_handle h;unsigned short port;CHECK(rtsp_owned_prepare(&o,&h)==0);seed(h,0x42);CHECK(rtsp_owned_start(h,&port)==0);int fd=connect_to(port);setup_play(fd);seed(h,0x42);receive_rtp(fd);uint32_t first=report(fd,3,13);seed(h,0x42);receive_rtp(fd);CHECK(report(fd,6,26)==first);CHECK(rtsp_owned_finish(h)==0);check_eof(fd);printf("owned periodic compound RTCP/cumulative counters/clock PASS: %u assertions\n",checks);}
